def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def count_passing_ways(n: int, m: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1 if m == 0 else 0
    # Use two arrays to store current and next step counts
    current = [0] * n
    current[0] = 1  # start at student 0
    for _ in range(m):
        next_step = [0] * n
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            next_step[i] = current[left] + current[right]
        current = next_step
    return current[0]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    if A == B:
        return 0

    max_steps = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping replacements
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    start = str(n)
    visited = {start}
    queue = [start]

    # Build a mapping from digit to list of possible replacements
    rule_map = {}
    for x, y in rules:
        rule_map.setdefault(str(x), []).append(str(y))

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            if ch in rule_map:
                for rep in rule_map[ch]:
                    new_num = current[:i] + rep + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    """
    # Normalize names to upper case for comparison
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    day_set = {day.upper() for day in days_of_week}

    for speaker, stmts in statements.items():
        speaker_name = speaker.upper()
        for stmt in stmts:
            # Skip statements that mention a day of the week
            stmt_upper = stmt.upper()
            if any(day in stmt_upper for day in day_set):
                continue

            truth = None
            # Handle "I am guilty" / "I am not guilty"
            if "I AM GUILTY" in stmt_upper:
                truth = (speaker_name == scenario)
            elif "I AM NOT GUILTY" in stmt_upper:
                truth = (speaker_name != scenario)
            else:
                # Handle "<NAME> is guilty" / "<NAME> is not guilty"
                if " IS GUILTY" in stmt_upper:
                    idx = stmt_upper.find(" IS GUILTY")
                    name = stmt[:idx].strip().upper()
                    truth = (name == scenario)
                elif " IS NOT GUILTY" in stmt_upper:
                    idx = stmt_upper.find(" IS NOT GUILTY")
                    name = stmt[:idx].strip().upper()
                    truth = (name != scenario)

            # If the statement doesn't match known patterns, ignore it
            if truth is None:
                continue

            # Check consistency with liar status
            if speaker_name in liar_set:
                if truth:  # liar should not make a true statement
                    return False
            else:
                if not truth:  # non-liar should not make a false statement
                    return False

    return True

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        new_dp = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                new_dp[j] = prefix[j]
            else:
                new_dp[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp = new_dp
    return dp[m] % MOD

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
